#include <bits/stdc++.h>
using namespace std;
const int MAXNODES = 10000, MAXEDGES = MAXNODES * 100;
const long long INF = LLONG_MAX >> 5;

struct Edge {
    int to; long long capacity; int cost; int rev;
};

class CostFlow {
private:
    int n;
    std::vector<std::vector<Edge>> adj;
    std::vector<long long> dist;
    std::vector<int> parent;
    std::vector<int> parentEdge;
    long long totalCost;
public:
    CostFlow(int n): n(n) {
        adj.resize(n);
        dist.resize(n);
        parent.resize(n);
        parentEdge.resize(n);
        totalCost = 0;
    }

    void addEdge(int u, int v, long long cap, int cst) {
        adj[u].push_back({v, cap, cst, (int)adj[v].size()});
        adj[v].push_back({u, 0, -cst, (int)adj[u].size() - 1});
    }

    long long computeMinCostFlow(int s, int t) {
        long long flow = 0;
        while (true) {
            std::fill(dist.begin(), dist.end(), LLONG_MAX);
            dist[s] = 0;
            std::queue<int> q; q.push(s);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int i = 0; i < (int)adj[u].size(); i++) {
                    Edge &e = adj[u][i];
                    if (e.capacity > 0 && dist[u] + e.cost < dist[e.to]) {
                        dist[e.to] = dist[u] + e.cost;
                        parent[e.to] = u;
                        parentEdge[e.to] = i;
                        q.push(e.to);
                    }
                }
            }
            if (dist[t] == LLONG_MAX) break;
            long long pushFlow = LLONG_MAX;
            for (int v = t; v != s; v = parent[v]) {
                int u = parent[v];
                pushFlow = min(pushFlow, (long long)adj[u][parentEdge[v]].capacity);
            }
            for (int v = t; v != s; v = parent[v]) {
                int u = parent[v];
                adj[u][parentEdge[v]].capacity -= pushFlow;
                adj[v][adj[u][parentEdge[v]].rev].capacity += pushFlow;
                totalCost += pushFlow * adj[u][parentEdge[v]].cost;
            }
            flow += pushFlow;
        }
        return totalCost;
    }
};

int main() {
    ios::sync_with_stdio(false);
    int n, m, kk, c, d; cin >> n >> m >> kk >> c >> d;
    int a[55]; for (int i = 1; i <= kk; i++) cin >> a[i];
    int s = 0, t = n * 100 + 1;
    CostFlow flow(n * 100 + 2);
    for (int i = 1; i <= 100; i++) flow.addEdge(i, t, INF, 0);
    for (int i = 1; i <= kk; i++) flow.addEdge(s, (a[i] - 1) * 100 + 1, 1, 0);
    for (int i = 2; i <= n; i++)
        for (int j = 1; j < 100; j++)
            flow.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, INF, c);
    int t1, t2;
    for (int _ = 1; _ <= m; _++) {
        cin >> t1 >> t2;
        for (int i = 1; i < 100; i++)
            for (int j = 1; j <= kk; j++) {
                int val = c + d * (j * j - (j - 1) * (j - 1));
                flow.addEdge((t1 - 1) * 100 + i, (t2 - 1) * 100 + i + 1, 1, val);
                flow.addEdge((t2 - 1) * 100 + i, (t1 - 1) * 100 + i + 1, 1, val);
            }
    }
    cout << flow.computeMinCostFlow(s, t) << endl;
    return 0;
}
